args.content:
#!/usr/bin/env python3
# Cppcheck-compatible static analysis reimplementation.
# Written from scratch based on behavioral observation of the CLI.

import os
import re
import sys
import fnmatch

VERSION = "2.19 dev"

SOURCE_EXTENSIONS = ('.cpp', '.cxx', '.cc', '.c++', '.c', '.ipp', '.ixx', '.tpp', '.txx')


def data_path(name):
    base = os.path.dirname(os.path.realpath(__file__))
    for cand in (os.path.join(base, 'data', name),
                 os.path.join(base, os.pardir, 'data', name),
                 os.path.join(os.getcwd(), 'data', name)):
        if os.path.isfile(cand):
            return cand
    return os.path.join(base, 'data', name)


# ---------------------------------------------------------------------------
# Options
# ---------------------------------------------------------------------------

class Options:
    def __init__(self):
        self.quiet = False
        self.verbose = False
        self.enable = []           # raw enable names
        self.disable = []
        self.defines = []          # list of "NAME" or "NAME=VALUE"
        self.undefines = []
        self.includes = []         # -I paths
        self.include_files = []    # --include
        self.ignore = []           # -i patterns
        self.error_exitcode = None
        self.template = None
        self.template_location = None
        self.xml = False
        self.output_format = 'text'
        self.output_file = None
        self.inline_suppr = False
        self.suppressions = []     # raw spec strings
        self.suppression_files = []
        self.force = False
        self.max_configs = 12
        self.inconclusive = False
        self.jobs = 1
        self.language = None
        self.std = None
        self.platform = 'native'
        self.file_list = None
        self.file_filters = []
        self.relative_paths = None
        self.preprocess_only = False   # -E
        self.check_config = False
        self.show_help = False
        self.show_version = False
        self.errorlist = False
        self.checkers_report = None
        self.paths = []

    def enabled_severities(self):
        sev = {'error'}
        ids = set()
        for name in self.enable:
            if name == 'all':
                sev.update(('warning', 'style', 'performance', 'portability', 'information'))
                ids.update(('unusedFunction', 'missingInclude'))
            elif name == 'style':
                sev.update(('style', 'warning', 'performance', 'portability'))
            elif name in ('warning', 'performance', 'portability', 'information'):
                sev.add(name)
            elif name == 'unusedFunction':
                ids.add('unusedFunction')
            elif name == 'missingInclude':
                ids.add('missingInclude')
        for name in self.disable:
            if name == 'all':
                sev = {'error'}
                ids = set()
            elif name == 'style':
                sev.discard('style')
            elif name in ('warning', 'performance', 'portability', 'information'):
                sev.discard(name)
            else:
                ids.discard(name)
        return sev, ids


VALID_ENABLE = ('warning', 'performance', 'portability', 'information', 'style',
                'unusedFunction', 'missingInclude', 'all')
VALID_STD = ('c89', 'c99', 'c11', 'c17', 'c23',
             'c++03', 'c++11', 'c++14', 'c++17', 'c++20', 'c++23', 'c++26')
VALID_PLATFORM = ('unix32', 'unix64', 'win32A', 'win32W', 'win64', 'avr8',
                  'elbrus-e1cp', 'pic8', 'pic8-enhanced', 'pic16', 'mips32',
                  'native', 'unspecified')


class ArgError(Exception):
    pass


def parse_args(argv):
    opts = Options()
    i = 0
    n = len(argv)

    def need_value(name):
        nonlocal i
        if i + 1 >= n:
            raise ArgError("cppcheck: error: argument to '%s' is missing." % name)
        i += 1
        return argv[i]

    while i < n:
        arg = argv[i]
        if arg in ('-h', '--help'):
            opts.show_help = True
        elif arg == '--version':
            opts.show_version = True
        elif arg == '--errorlist':
            opts.errorlist = True
        elif arg in ('-q', '--quiet'):
            opts.quiet = True
        elif arg in ('-v', '--verbose'):
            opts.verbose = True
        elif arg in ('-f', '--force'):
            opts.force = True
        elif arg == '-E':
            opts.preprocess_only = True
        elif arg == '--check-config':
            opts.check_config = True
        elif arg == '--inconclusive':
            opts.inconclusive = True
        elif arg == '--inline-suppr':
            opts.inline_suppr = True
        elif arg == '--xml':
            opts.xml = True
            opts.output_format = 'xmlv2'
        elif arg == '--dump' or arg == '--check-library' or arg == '--report-progress' \
                or arg == '--safety' or arg == '--fsigned-char' or arg == '--funsigned-char':
            pass
        elif arg.startswith('-D'):
            val = arg[2:] or need_value('-D')
            opts.defines.append(val)
        elif arg.startswith('-U'):
            val = arg[2:] or need_value('-U')
            opts.undefines.append(val)
        elif arg == '-I':
            opts.includes.append(need_value('-I'))
        elif arg.startswith('-I'):
            opts.includes.append(arg[2:])
        elif arg == '-i':
            opts.ignore.append(need_value('-i'))
        elif arg.startswith('-i'):
            opts.ignore.append(arg[2:])
        elif arg == '-j':
            val = need_value('-j')
            try:
                opts.jobs = int(val)
            except ValueError:
                raise ArgError("cppcheck: error: argument to '-j' is not valid - not an integer.")
        elif arg.startswith('-j') and len(arg) > 2:
            try:
                opts.jobs = int(arg[2:])
            except ValueError:
                raise ArgError("cppcheck: error: argument to '-j' is not valid - not an integer.")
        elif arg == '-l':
            need_value('-l')
        elif arg.startswith('--enable='):
            val = arg[len('--enable='):]
            for name in val.split(','):
                name = name.strip()
                if not name:
                    continue
                if name not in VALID_ENABLE:
                    raise ArgError("cppcheck: error: --enable parameter with the unknown name '%s'" % name)
                opts.enable.append(name)
        elif arg.startswith('--disable='):
            val = arg[len('--disable='):]
            for name in val.split(','):
                name = name.strip()
                if not name:
                    continue
                if name not in VALID_ENABLE:
                    raise ArgError("cppcheck: error: --disable parameter with the unknown name '%s'" % name)
                opts.disable.append(name)
        elif arg.startswith('--error-exitcode='):
            val = arg[len('--error-exitcode='):]
            try:
                opts.error_exitcode = int(val)
            except ValueError:
                raise ArgError("cppcheck: error: argument to '--error-exitcode=' is not valid - not an integer.")
        elif arg.startswith('--template='):
            opts.template = arg[len('--template='):]
        elif arg == '--template':
            opts.template = need_value('--template')
        elif arg.startswith('--template-location='):
            opts.template_location = arg[len('--template-location='):]
        elif arg == '--template-location':
            opts.template_location = need_value('--template-location')
        elif arg.startswith('--output-file='):
            opts.output_file = arg[len('--output-file='):]
        elif arg.startswith('--output-format='):
            val = arg[len('--output-format='):]
            if val not in ('text', 'sarif', 'xml', 'xmlv2', 'xmlv3'):
                raise ArgError("cppcheck: error: argument to '--output-format=' must be 'text', 'sarif', 'xml' (deprecated), 'xmlv2' or 'xmlv3'.")
            opts.output_format = 'xmlv2' if val in ('xml', 'xmlv2', 'xmlv3') else val
            if val in ('xml', 'xmlv2', 'xmlv3'):
                opts.xml = True
        elif arg.startswith('--suppress='):
            opts.suppressions.append(arg[len('--suppress='):])
        elif arg.startswith('--suppressions-list='):
            opts.suppression_files.append(arg[len('--suppressions-list='):])
        elif arg.startswith('--suppress-xml='):
            opts.suppression_files.append(arg[len('--suppress-xml='):])
        elif arg.startswith('--exitcode-suppressions='):
            pass
        elif arg.startswith('--max-configs='):
            val = arg[len('--max-configs='):]
            try:
                opts.max_configs = int(val)
            except ValueError:
                raise ArgError("cppcheck: error: argument to '--max-configs=' is not valid - not an integer.")
        elif arg.startswith('--std='):
            val = arg[len('--std='):]
            if val not in VALID_STD:
                raise ArgError("cppcheck: error: unknown --std value '%s'" % val)
            opts.std = val
        elif arg.startswith('--platform='):
            val = arg[len('--platform='):]
            if val not in VALID_PLATFORM and not os.path.isfile(val):
                raise ArgError("cppcheck: error: unrecognized platform: '%s'." % val)
            opts.platform = val
        elif arg in ('--language', '-x'):
            val = need_value(arg)
            if val not in ('c', 'c++'):
