# ---------------------------------------------------------------------------
# Tokenizer
# ---------------------------------------------------------------------------

class Token:
    __slots__ = ('s', 'line', 'col', 'idx')

    def __init__(self, s, line, col, idx=-1):
        self.s = s
        self.line = line
        self.col = col
        self.idx = idx

    def __repr__(self):
        return '<%s %d:%d>' % (self.s, self.line, self.col)


MULTI_OPS = (
    '<<=', '>>=', '->*', '...', '++', '--', '->', '<<', '>>', '<=', '>=',
    '==', '!=', '&&', '||', '+=', '-=', '*=', '/=', '%=', '&=', '|=',
    '^=', '::', '.*', '##',
)

IDENT_RE = re.compile(r'[A-Za-z_][A-Za-z0-9_]*')
NUM_RE = re.compile(r"(?:0[xX][0-9a-fA-F']+|0[bB][01']+|\d[\d']*(?:\.\d[\d']*)?(?:[eE][+-]?\d+)?)[uUlLfF]*")


def tokenize_line(line, lineno, tokens):
    """Tokenize one source line, appending Token objects."""
    i = 0
    n = len(line)
    while i < n:
        c = line[i]
        if c in ' \t\r':
            i += 1
            continue
        col = i + 1
        if c == '"' or c == "'":
            j = i + 1
            while j < n:
                if line[j] == '\\':
                    j += 2
                    continue
                if line[j] == c:
                    j += 1
                    break
                j += 1
            tokens.append(Token(line[i:j], lineno, col))
            i = j
            continue
        m = IDENT_RE.match(line, i)
        if m:
            # raw string literal R"(...)"
            if m.group(0) == 'R' and m.end() < n and line[m.end()] == '"':
                j = line.find('"', m.end() + 1)
                j = n if j < 0 else j + 1
                tokens.append(Token(line[i:j], lineno, col))
                i = j
                continue
            tokens.append(Token(m.group(0), lineno, col))
            i = m.end()
            continue
        m = NUM_RE.match(line, i)
        if m and m.group(0):
            tokens.append(Token(m.group(0), lineno, col))
            i = m.end()
            continue
        matched = False
        for op in MULTI_OPS:
            if line.startswith(op, i):
                tokens.append(Token(op, lineno, col))
                i += len(op)
                matched = True
                break
        if matched:
            continue
        tokens.append(Token(c, lineno, col))
        i += 1


def strip_comments(text):
    """Replace comments with whitespace (preserving newlines). Returns
    cleaned text and a list of (line, text) for cppcheck-suppress comments."""
    out = []
    suppr = []
    i = 0
    n = len(text)
    lineno = 1
    while i < n:
        c = text[i]
        if c == '\n':
            out.append('\n')
            lineno += 1
            i += 1
        elif c == '/' and i + 1 < n and text[i + 1] == '/':
            j = text.find('\n', i)
            if j < 0:
                j = n
            comment = text[i:j]
            if 'cppcheck-suppress' in comment:
                suppr.append((lineno, comment))
            out.append(' ' * (j - i))
            i = j
        elif c == '/' and i + 1 < n and text[i + 1] == '*':
            j = text.find('*/', i + 2)
            if j < 0:
                j = n - 2
            comment = text[i:j + 2]
            if 'cppcheck-suppress' in comment:
                suppr.append((lineno, comment))
            for ch in comment:
                out.append('\n' if ch == '\n' else ' ')
                if ch == '\n':
                    lineno += 1
            i = j + 2
        elif c == '"' or c == "'":
            j = i + 1
            while j < n:
                if text[j] == '\\':
                    j += 2
                    continue
                if text[j] == c or text[j] == '\n':
                    break
                j += 1
            out.append(text[i:j + 1] if j < n else text[i:])
            i = j + 1 if j < n else n
        else:
            out.append(c)
            i += 1
    return ''.join(out), suppr


# ---------------------------------------------------------------------------
# Preprocessor (simplified)
# ---------------------------------------------------------------------------

DIRECTIVE_RE = re.compile(r'^\s*#\s*([A-Za-z_]+)\s*(.*)$')


def eval_pp_expr(expr, defines):
    """Evaluate a #if expression (very small subset)."""
    def repl_defined(m):
        return '1' if m.group(1) in defines else '0'
    expr = re.sub(r'defined\s*\(\s*([A-Za-z_][A-Za-z0-9_]*)\s*\)', repl_defined, expr)
    expr = re.sub(r'defined\s+([A-Za-z_][A-Za-z0-9_]*)', repl_defined, expr)

    def repl_ident(m):
        name = m.group(0)
        val = defines.get(name)
        if val is None:
            return '0'
        val = val.strip()
        return val if re.match(r'^-?\d+$', val) else '1'
    expr = IDENT_RE.sub(repl_ident, expr)
    expr = expr.replace('&&', ' and ').replace('||', ' or ')
    expr = re.sub(r'!(?!=)', ' not ', expr)
    try:
        return bool(eval(expr, {'__builtins__': {}}, {}))
    except Exception:
        return False


def find_config_macros(lines, user_undefs):
    """Collect macros tested in #if* directives, in first-appearance order."""
    macros = []
    seen = set()
    for line in lines:
        m = DIRECTIVE_RE.match(line)
        if not m:
            continue
        directive, rest = m.group(1), m.group(2)
        if directive in ('ifdef', 'ifndef'):
            name = rest.strip().split()[0] if rest.strip() else ''
            if name and name not in seen and name not in user_undefs:
                seen.add(name)
                macros.append(name)
        elif directive in ('if', 'elif'):
            rest2 = re.sub(r'defined\s*\(\s*([A-Za-z_][A-Za-z0-9_]*)\s*\)', r'\1', rest)
            rest2 = re.sub(r'defined\s+([A-Za-z_][A-Za-z0-9_]*)', r'\1', rest2)
            for name in IDENT_RE.findall(rest2):
                if name in seen or name in user_undefs:
                    continue
                if name in ('and', 'or', 'not'):
                    continue
                seen.add(name)
                macros.append(name)
    return macros


def preprocess(lines, defines):
    """Return list of (lineno, text) for lines active in this configuration.
    `defines` maps name -> value string. Handles #define/#undef/#if*."""
    defines = dict(defines)
    # stack entries: [parent_active, branch_taken, active]
    stack = []
    active = True
    kept = []
    includes = []  # (lineno, col, kind, name) kind: 'system' or 'local'
    for idx, line in enumerate(lines):
        lineno = idx + 1
        m = DIRECTIVE_RE.match(line)
        if m:
            directive, rest = m.group(1), m.group(2)
            if directive == 'ifdef':
                name = rest.strip().split()[0] if rest.strip() else ''
                cond = name in defines
                stack.append([active, cond, active and cond])
                active = active and cond
            elif directive == 'ifndef':
                name = rest.strip().split()[0] if rest.strip() else ''
                cond = name not in defines
                stack.append([active, cond, active and cond])
                active = active and cond
            elif directive == 'if':
                cond = eval_pp_expr(rest, defines)
                stack.append([active, cond, active and cond])
                active = active and cond
            elif directive == 'elif':
                if stack:
                    top = stack[-1]
                    if top[1]:
                        top[2] = False
                    else:
                        cond = eval_pp_expr(rest, defines)
                        top[2] = top[0] and cond
                        top[1] = cond
                    active = top[2]
            elif directive == 'else':
                if stack:
                    top = stack[-1]
                    top[2] = top[0] and not top[1]
                    top[1] = True
                    active = top[2]
            elif directive == 'endif':
                if stack:
                    stack.pop()
                active = stack[-1][2] if stack else True
            elif not active:
                pass
            elif directive == 'define':
                dm = re.match(r'([A-Za-z_][A-Za-z0-9_]*)(\(([^)]*)\))?\s*(.*)$', rest.strip())
                if dm and not dm.group(2):  # object-like only
                    defines[dm.group(1)] = dm.group(4).strip()
            elif directive == 'undef':
                name = rest.strip().split()[0] if rest.strip() else ''
                defines.pop(name, None)
            elif directive == 'include':
                im = re.match(r'\s*<([^>]*)>', rest)
                if im:
                    col = line.find('include') + 1
                    includes.append((lineno, col, 'system', im.group(1)))
                else:
                    im = re.match(r'\s*"([^"]*)"', rest)
                    if im:
                        col = line.find('include') + 1
                        includes.append((lineno, col, 'local', im.group(1)))
            continue
        if active:
            kept.append((lineno, line))
    return kept, includes


def substitute_macros(tokens, defines):
    """Simple object-like macro substitution (numeric/simple defines)."""
    out = []
    for tok in tokens:
        if tok.s in defines and IDENT_RE.fullmatch(tok.s):
            val = defines[tok.s]
            if val == '':
                continue
            parts = val.split()
            if all(re.fullmatch(r'-?\d+', p) for p in parts):
                for p in parts:
                    out.append(Token(p, tok.line, tok.col))
                continue
        out.append(tok)
    return out
